// Builds the inlined front-end assets for TestBox's HTML reporters into system/reports/assets/vendor.
//   npm ci && npm run build     regenerate everything from the pinned versions
//   npm run check               fail if the committed files differ from a fresh build (used in CI)
//   npm run update              bump pinned versions, install, then rebuild
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname( fileURLToPath( import.meta.url ) );
const outDir = resolve( here, "../../system/reports/assets/vendor" );
const nm = ( ...p ) => join( here, "node_modules", ...p );
const checkOnly = process.argv.includes( "--check" );
const pkg = JSON.parse( readFileSync( join( here, "package.json" ), "utf8" ) );
const version = ( name ) => JSON.parse( readFileSync( nm( name, "package.json" ), "utf8" ) ).version;

const stripMaps = ( text ) =>
	text.replace( /\/\*# sourceMappingURL=.*?\*\//g, "" ).replace( /\/\/# sourceMappingURL=.*/g, "" ).trimEnd() + "\n";
const read = ( ...p ) => readFileSync( nm( ...p ), "utf8" );

// ---- icon sprite ----
const icons = readFileSync( join( here, "icons.txt" ), "utf8" )
	.split( "\n" )
	.map( ( l ) => l.trim() )
	.filter( ( l ) => l && !l.startsWith( "#" ) );
const symbols = icons.map( ( name ) => {
	const file = nm( "bootstrap-icons", "icons", `${ name }.svg` );
	if ( !existsSync( file ) ) throw new Error( `Unknown Bootstrap Icon "${ name }" in icons.txt` );
	const inner = readFileSync( file, "utf8" ).match( /<svg[^>]*>([\s\S]*)<\/svg>/ )[ 1 ].trim();
	return `<symbol id="i-${ name }" viewBox="0 0 16 16" fill="currentColor">${ inner }</symbol>`;
} );
const sprite = `<svg xmlns="http://www.w3.org/2000/svg" hidden aria-hidden="true" style="display:none">\n${ symbols.join( "\n" ) }\n</svg>\n`;

// ---- prism: core + the languages TestBox shows, one file ----
const prismParts = [
	"window.Prism=window.Prism||{};window.Prism.manual=true;",
	read( "prismjs", "components", "prism-core.min.js" ),
	read( "prismjs", "components", "prism-clike.min.js" ),
	read( "prismjs", "components", "prism-cfscript.min.js" ),
	readFileSync( join( here, "prism-boxlang.js" ), "utf8" )
];

const licenses = [ "bootstrap", "alpinejs", "bootstrap-icons", "prismjs" ].map( ( name ) => {
	const file = [ "LICENSE", "LICENSE.md", "LICENSE.txt" ].map( ( f ) => nm( name, f ) ).find( existsSync );
	let text;
	if ( file ) {
		text = readFileSync( file, "utf8" ).trim();
	} else {
		// Some packages (alpinejs) ship no license file: record what their package.json declares.
		const meta = JSON.parse( readFileSync( nm( name, "package.json" ), "utf8" ) );
		const author = typeof meta.author === "string" ? meta.author : meta.author?.name ?? "the authors";
		text = `${ name } is licensed under the ${ meta.license } license. Author: ${ author }. Source: ${ meta.homepage ?? meta.repository?.url ?? "see the package" }.`;
	}
	return `===== ${ name } ${ version( name ) } =====\n${ text }\n`;
} );

const files = {
	"bootstrap.min.css" : stripMaps( read( "bootstrap", "dist", "css", "bootstrap.min.css" ) ),
	"alpine.min.js"     : stripMaps( read( "alpinejs", "dist", "cdn.min.js" ) ),
	"prism.min.js"      : prismParts.map( stripMaps ).join( "\n" ),
	"icons.svg"         : sprite,
	"LICENSES.txt"      : licenses.join( "\n" )
};
const manifest = {
	_note : "Generated by build/vendor/build.mjs. Do not edit by hand.",
	versions : Object.fromEntries( Object.keys( pkg.dependencies ).map( ( n ) => [ n, version( n ) ] ) ),
	icons,
	sha256 : Object.fromEntries( Object.entries( files ).map( ( [ n, c ] ) => [ n, createHash( "sha256" ).update( c ).digest( "hex" ) ] ) )
};
files[ "VERSIONS.json" ] = JSON.stringify( manifest, null, "\t" ) + "\n";

let stale = [];
if ( !checkOnly ) mkdirSync( outDir, { recursive : true } );
for ( const [ name, content ] of Object.entries( files ) ) {
	const target = join( outDir, name );
	if ( checkOnly ) {
		if ( !existsSync( target ) || readFileSync( target, "utf8" ) !== content ) stale.push( name );
	} else {
		writeFileSync( target, content );
		console.log( `wrote ${ name } (${ ( Buffer.byteLength( content ) / 1024 ).toFixed( 1 ) } KB)` );
	}
}
if ( checkOnly ) {
	if ( stale.length ) {
		console.error( `Out of date: ${ stale.join( ", " ) }\nRun "npm ci && npm run build" in build/vendor and commit the result.` );
		process.exit( 1 );
	}
	console.log( "Vendored report assets are up to date." );
}
